<h1>Quản lý điểm học tập</h1><p class="muted">Điểm tổng kết hệ 10 = Điểm quá trình × 40% + Điểm thi × 60%. Đạt khi điểm tổng kết từ 5,00 trở lên (quy tắc minh họa).</p>
<section class="panel"><h2><?= current_user()['role']==='student'?'Bảng điểm của tôi':'Danh sách bảng điểm' ?></h2><div class="tablewrap"><table><thead><tr><th>Đăng ký</th><th>MSSV</th><th>Họ tên</th><th>Học phần</th><th>Học kỳ</th><th>Quá trình</th><th>Thi</th><th>Tổng kết</th><th>Kết quả</th><?php if(current_user()['role']!=='student'): ?><th>Nhập / sửa điểm</th><?php endif; ?></tr></thead><tbody>
<?php foreach($rows as $r): $hasGrade=$r['average_score']!==null; ?><tr><td><?= e($r['enrollment_id']) ?></td><td><?= e($r['student_code']) ?></td><td><?= e($r['student_name']) ?></td><td><?= e($r['course_code'].' - '.$r['course_name']) ?></td><td><?= e($r['semester']) ?></td><td><?= e($r['process_score']??'—') ?></td><td><?= e($r['final_score']??'—') ?></td><td><?= $hasGrade?e(number_format((float)$r['average_score'],2)):'—' ?></td><td><?php if($hasGrade): ?><span class="<?= (float)$r['average_score']>=5?'scorepass':'scorefail' ?>"><?= (float)$r['average_score']>=5?'Đạt':'Chưa đạt' ?></span><?php else: ?>Chưa có điểm<?php endif; ?></td>
<?php if(current_user()['role']!=='student'): ?><td><form class="actions" method="post" action="<?= e(url('grades-save')) ?>"><?= csrf_input() ?><input type="hidden" name="enrollment_id" value="<?= e($r['enrollment_id']) ?>"><input aria-label="Điểm quá trình" type="number" name="process_score" min="0" max="10" step="0.01" value="<?= e($r['process_score']??'') ?>" required style="width:75px;margin:0"><input aria-label="Điểm thi" type="number" name="final_score" min="0" max="10" step="0.01" value="<?= e($r['final_score']??'') ?>" required style="width:75px;margin:0"><button>Lưu</button></form></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div></section>
